-- Generated from lib/seed-data.ts. Re-run with: npx tsx scripts/emit-seed-sql.ts
-- Replaces this owner's shelf, including the earlier demo titles. Borrow rows cascade.
delete from books where owner_id = '00000000-0000-4000-8000-000000000001';
insert into books (
  id, owner_id, title, author, cover_url, synopsis, genre, format, rating, review, isbn, status, created_at
) values
  ('10000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-000000000001', 'Harry Potter and the Half-Blood Prince', 'J.K. Rowling', '/api/cover?id=10716273', 'In his sixth year at Hogwarts, Harry is pulled out of ordinary schoolwork and into Dumbledore''s private lessons about the childhood of Lord Voldemort. A new potions teacher, a cursed piece of jewelry, and a romance he cannot quite manage all run alongside that history. The year ends with a choice on the Astronomy Tower that the school cannot undo.', 'Fantasy', 'physical', null, null, '9780439785969', 'available', '2024-01-01T00:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000002', '00000000-0000-4000-8000-000000000001', 'Harry Potter and the Deathly Hallows', 'J.K. Rowling', '/api/cover?id=15158660', 'Harry leaves school without a plan except to find and destroy the objects that keep Voldemort alive. He, Ron, and Hermione move through a country at war, hunted, short of food, and increasingly unsure of one another. The search leads back to Hogwarts, and to three objects from an old children''s story that offer another way to face death.', 'Fantasy', 'physical', null, null, '9780545139700', 'available', '2024-01-02T00:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000003', '00000000-0000-4000-8000-000000000001', 'Fantastic Beasts: The Original Screenplay', 'J.K. Rowling', '/api/cover?id=7884242', 'Newt Scamander arrives in 1926 New York with a suitcase full of magical creatures, and several of them get out. While he tries to recover them, a darker force is attacking the city and the wizarding world is blaming everything it does not understand. The screenplay follows the chase through speakeasies, a newspaper, and a family that has been taught to hate magic.', 'Fantasy', 'physical', null, null, '9781338109061', 'available', '2024-01-03T00:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000004', '00000000-0000-4000-8000-000000000001', 'Six of Crows', 'Leigh Bardugo', '/api/cover?id=12667417', 'Kaz Brekker is offered a fortune to break a prisoner out of the Ice Court, the most guarded place in a hostile country. He assembles five criminals who do not trust him or each other: a gambler, a runaway, a soldier, a demolitions expert, and a spy. The plan depends on timing, disguises, and the hope that none of them will sell the others out before the job is done.', 'Fantasy', 'physical', null, null, '9781627792127', 'available', '2024-01-04T00:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000005', '00000000-0000-4000-8000-000000000001', 'The Mark of Athena', 'Rick Riordan', '/api/cover?id=12848680', 'Seven demigods from the Greek and Roman camps sail together toward an ancient goal, already half ready to fight one another. Annabeth is sent alone into Rome to follow the mark of Athena, a trail left for a child of wisdom. Above ground the crew tries to keep the ship in one piece. Below it, she has to walk a path that was built to kill her.', 'Fantasy', 'physical', null, null, '9781423140603', 'available', '2024-01-05T00:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000006', '00000000-0000-4000-8000-000000000001', 'The Cruel Prince', 'Holly Black', '/api/cover?id=8361789', 'Jude and her sisters are raised in the High Court of Faerie by the man who killed their parents. She cannot do magic, so she studies swordplay, poison, and the court''s rules instead. A place beside Prince Cardan looks like humiliation until she realizes the throne is weaker than it pretends, and that a mortal who understands the game can take a piece of it.', 'Fantasy', 'physical', null, null, '9780316310277', 'available', '2024-01-06T00:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000007', '00000000-0000-4000-8000-000000000001', 'The Queen of Nothing', 'Holly Black', '/api/cover?id=9146990', 'Jude is exiled to the mortal world after being betrayed, while Cardan remains on the throne she helped him take. A sister''s plea pulls her back into Faerie, where a curse is spreading and the court still prefers a beautiful lie to a plain truth. She has to decide what she is willing to become in order to hold a kingdom that was never meant to be hers.', 'Fantasy', 'physical', null, null, '9780316310383', 'available', '2024-01-07T00:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000008', '00000000-0000-4000-8000-000000000001', 'The Fellowship of the Ring', 'J.R.R. Tolkien', '/api/cover?id=14627060', 'A hobbit inherits a ring that wants to return to its maker, and the quiet of the Shire cannot protect him once its servants know where it is. Frodo sets out with companions who agree, for a while, to walk the same road: men, a dwarf, an elf, a wizard, and other hobbits. The company breaks on the journey toward Mordor, and the smallest of them has to go on without the protection he started with.', 'Fantasy', 'physical', null, null, '9780547928210', 'available', '2024-01-08T00:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000009', '00000000-0000-4000-8000-000000000001', 'The Fellowship of the Ring', 'J.R.R. Tolkien', '/api/cover?id=14627060', 'A hobbit inherits a ring that wants to return to its maker, and the quiet of the Shire cannot protect him once its servants know where it is. Frodo sets out with companions who agree, for a while, to walk the same road: men, a dwarf, an elf, a wizard, and other hobbits. The company breaks on the journey toward Mordor, and the smallest of them has to go on without the protection he started with. This is the second copy.', 'Fantasy', 'physical', null, null, '9780547928210', 'available', '2024-01-09T00:00:00.000Z'),
  ('10000000-0000-4000-8000-00000000000a', '00000000-0000-4000-8000-000000000001', 'The Lord of the Rings', 'J.R.R. Tolkien', '/api/cover?id=14625765', 'The whole story of the Ring, from the Shire to the War of the Ring, in a single volume. Frodo carries the Ring toward the one fire that can unmake it, while his friends fight a war meant to give him time. The book is as interested in the long walk home, and in what power costs the people who refuse it, as it is in the battles.', 'Fantasy', 'physical', null, null, '9780618640157', 'available', '2024-01-10T00:00:00.000Z'),
  ('10000000-0000-4000-8000-00000000000b', '00000000-0000-4000-8000-000000000001', 'Crooked Kingdom', 'Leigh Bardugo', '/api/cover?id=12667428', 'The Ice Court job is over, and Ketterdam wants its money back. Kaz''s crew is scattered, injured, and holding a prisoner too valuable to keep and too dangerous to release. To survive the city''s merchants, gangs, and their own bargains, they have to run a second scheme in the place they supposedly know best.', 'Fantasy', 'physical', null, null, '9781627792134', 'available', '2024-01-11T00:00:00.000Z'),
  ('10000000-0000-4000-8000-00000000000c', '00000000-0000-4000-8000-000000000001', 'Prince Caspian', 'C.S. Lewis', '/api/cover?id=45897', 'A thousand years after they left, the Pevensie children are pulled back into Narnia and find the land under a Telmarine king who has tried to erase its talking beasts and old stories. Prince Caspian, the rightful heir, is in hiding with the creatures who still remember. The children have to help him take the country back before the old Narnia is gone for good.', 'Fantasy', 'physical', null, null, '9780064471053', 'available', '2024-01-12T00:00:00.000Z'),
  ('10000000-0000-4000-8000-00000000000d', '00000000-0000-4000-8000-000000000001', 'The Ballad of Never After', 'Stephanie Garber', '/api/cover?id=12945180', 'Evangeline Fox made a bargain that was supposed to save the boy she loves, and it left him married to someone else and unable to tell her the truth. The story she is trapped in keeps rewriting itself, with knives, curses, and a fate that treats her hope as a plot device. She has to learn which version of Jacks, and of herself, is the one the story cannot kill.', 'Fantasy', 'physical', null, null, '9781250268419', 'available', '2024-01-13T00:00:00.000Z'),
  ('10000000-0000-4000-8000-00000000000e', '00000000-0000-4000-8000-000000000001', 'The Alchemist', 'Paulo Coelho', '/api/cover?id=15075893', 'Santiago, an Andalusian shepherd, dreams of a treasure buried near the Egyptian pyramids and sells his sheep to follow it. On the road he meets a king, a crystal merchant, an Englishman, and an alchemist, each of whom gives him a different lesson about desire and fear. The journey keeps turning him back toward the life he already had the means to notice.', 'Fantasy', 'physical', null, null, '9780062315007', 'available', '2024-01-14T00:00:00.000Z'),
  ('10000000-0000-4000-8000-00000000000f', '00000000-0000-4000-8000-000000000001', 'Valkyries', 'Paulo Coelho', '/api/cover?id=11737196', 'Paulo, a writer whose marriage is strained, travels into the Mojave Desert with his wife, Chris, to keep a promise he made on the road to Santiago. There he meets the Valkyries, a group of women who travel the desert and speak about breaking with the past. The book is a spiritual journey about jealousy, courage, and whether a person can actually change the agreements they have made with themselves.', 'Fantasy', 'physical', null, null, null, 'available', '2024-01-15T00:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000010', '00000000-0000-4000-8000-000000000001', 'The Little Prince', 'Antoine de Saint-Exupéry', '/api/cover?id=115508', 'A pilot stranded in the Sahara meets a small boy who says he has come from an asteroid, where he looks after a single rose. The boy describes the grown-ups he met on the way, each obsessed with numbers, power, or ownership. What he wants from the pilot is not rescue so much as a promise to remember that the important things are invisible.', 'Fantasy', 'physical', null, null, '9780156012195', 'available', '2024-01-16T00:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000011', '00000000-0000-4000-8000-000000000001', 'Harry Potter and the Cursed Child', 'J.K. Rowling, John Tiffany, and Jack Thorne', '/api/cover?id=8763851', 'Years after the war, Harry is a tired father and Albus is a son who does not want his father''s story. A conversation with Amos Diggory and a stolen Time-Turner send Albus and Scorpius Malfoy back into the past to save Cedric. Each change they make unravels the world they came from, and Harry has to face the part of himself he has been asking his son to carry.', 'Fantasy', 'physical', null, null, '9781338099133', 'available', '2024-01-17T00:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000012', '00000000-0000-4000-8000-000000000001', 'Lord of Shadows', 'Cassandra Clare', '/api/cover?id=8470222', 'Emma Carstairs and Julian Blackthorn are in love, which the Law of the Clave treats as a crime because they were raised as parabatai. The Blackthorn family is trying to protect a secret about Mark and Kieran, and about Ty''s grief, while a threat from Faerie moves closer to Los Angeles. The more Julian schemes to keep his family safe, the more he begins to resemble the coldness he is fighting.', 'Fantasy', 'physical', null, null, '9781442468405', 'available', '2024-01-18T00:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000013', '00000000-0000-4000-8000-000000000001', 'The Dark Artifices', 'Cassandra Clare', '/api/cover?id=8737541', 'This is the Los Angeles sequence about Emma Carstairs and the Blackthorns: a group of young Shadowhunters raising one another after a massacre, on the edge of a war with Faerie. Emma is bound to Julian as a parabatai and in love with him anyway, which the Clave would punish with madness or death. The set follows that forbidden love through sea demons, the Unseelie Court, and the question of how far Julian will go for the children in his care.', 'Fantasy', 'physical', null, null, null, 'available', '2024-01-19T00:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000014', '00000000-0000-4000-8000-000000000001', 'City of Ashes', 'Cassandra Clare', '/api/cover?id=1787130', 'After Clary Fray learns that her father is Valentine and that Jace may be her brother, the Shadowhunter world stops treating either of them as ordinary teenagers. Valentine steals the second Mortal Instrument and raises demons over New York, while the Clave closes in on Jace. Clary has to decide whom she believes, and what her new ability to create runes is for.', 'Fantasy', 'physical', null, null, '9781416914297', 'available', '2024-01-20T00:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000015', '00000000-0000-4000-8000-000000000001', 'Twilight', 'Stephenie Meyer', '/api/cover?id=12641977', 'Bella Swan moves to Forks, Washington, to live with her father and finds herself drawn to Edward Cullen, a boy whose family never eats, never seems to sleep, and avoids the sunlight. He is a vampire who has chosen not to hunt humans, and he wants her anyway. The attachment puts her in the path of a tracker who does not share the Cullens'' restraint.', 'Fantasy', 'physical', null, null, '9780316015844', 'available', '2024-01-21T00:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000016', '00000000-0000-4000-8000-000000000001', 'New Moon', 'Stephenie Meyer', '/api/cover?id=12643406', 'Edward leaves Bella, convinced he is the danger in her life, and the departure hollows her out. She finds a dangerous kind of comfort with Jacob Black, whose family is hiding a change of its own. When a misunderstanding puts Edward in the path of the Volturi, Bella has to cross into the vampire world again to stop him from a decision he cannot take back.', 'Fantasy', 'physical', null, null, '9780316160193', 'available', '2024-01-22T00:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000017', '00000000-0000-4000-8000-000000000001', 'Eclipse', 'Stephenie Meyer', '/api/cover?id=12643410', 'Victoria is building an army of newborn vampires to take Bella, while Edward and Jacob both want a future with her and cannot share it. The treaty between the Cullens and the wolves frays as they prepare to fight on the same side. Bella, who has asked to be changed, has to choose a life, and a war, before her graduation.', 'Fantasy', 'physical', null, null, '9780316160209', 'available', '2024-01-23T00:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000018', '00000000-0000-4000-8000-000000000001', 'Divergent', 'Veronica Roth', '/api/cover?id=13274634', 'In a walled Chicago, sixteen-year-olds choose a faction that will define their virtue for life: honesty, selflessness, bravery, kindness, or learning. Beatrice Prior leaves her selfless family for Dauntless and learns that her test result was Divergent, a mind the system cannot classify. The people who run the factions have a use for anyone who cannot be controlled.', 'Speculative', 'physical', null, null, '9780062024039', 'available', '2024-01-24T00:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000019', '00000000-0000-4000-8000-000000000001', 'Allegiant', 'Veronica Roth', '/api/cover?id=7276393', 'The faction system has fallen, and Tris and Tobias leave the city to find out who built it. Beyond the fence is a bureau that has been watching Chicago as an experiment in genetic damage and repair. The people inside the experiment and the people running it do not agree on what should happen next, and Tris is asked to pick a side that will cost her either way.', 'Speculative', 'physical', null, null, '9780062024060', 'available', '2024-01-25T00:00:00.000Z'),
  ('10000000-0000-4000-8000-00000000001a', '00000000-0000-4000-8000-000000000001', 'Four: A Divergent Collection', 'Veronica Roth', '/api/cover?id=7314248', 'Four stories from Tobias Eaton''s life before and alongside Divergent: his escape from his father''s abusive house, his choice of Dauntless, his rise inside that faction, and his first notice of Tris. Together they show how he learned to distrust the system he is very good at surviving. The pieces are his, not Tris''s, and they fill in the years the novel left offstage.', 'Speculative', 'physical', null, null, '9780062345219', 'available', '2024-01-26T00:00:00.000Z'),
  ('10000000-0000-4000-8000-00000000001b', '00000000-0000-4000-8000-000000000001', 'The Hunger Games', 'Suzanne Collins', '/api/cover?id=12646537', 'In Panem, each district must send a boy and a girl to fight to the death on television. When her younger sister is chosen, Katniss Everdeen volunteers in her place and enters the arena with Peeta Mellark, a boy who once kept her family from starving. The Games are designed to make the districts watch one another die. Katniss''s refusal to play them cleanly becomes a problem for the Capitol.', 'Speculative', 'physical', null, null, '9780439023481', 'available', '2024-01-27T00:00:00.000Z'),
  ('10000000-0000-4000-8000-00000000001c', '00000000-0000-4000-8000-000000000001', 'Catching Fire', 'Suzanne Collins', '/api/cover?id=12646539', 'Katniss and Peeta''s act of defiance has made them symbols, and President Snow wants the performance corrected on a Victory Tour. Resistance is already catching in the districts. For the 75th Games, the Capitol sends previous victors back into the arena, and Katniss has to decide whether she is willing to be the spark other people will burn for.', 'Speculative', 'physical', null, null, '9780439023498', 'available', '2024-01-28T00:00:00.000Z'),
  ('10000000-0000-4000-8000-00000000001d', '00000000-0000-4000-8000-000000000001', 'Mockingjay', 'Suzanne Collins', '/api/cover?id=12646459', 'Rescued from the arena and taken to District 13, Katniss is asked to become the face of a revolution she did not design. Peeta is in the Capitol''s hands, and the footage of him is being used against her. The war that follows asks what a symbol owes the people who carry it, and what remains of a person once the war has used her up.', 'Speculative', 'physical', null, null, '9780439023511', 'available', '2024-01-29T00:00:00.000Z'),
  ('10000000-0000-4000-8000-00000000001e', '00000000-0000-4000-8000-000000000001', 'The Ballad of Songbirds and Snakes', 'Suzanne Collins', '/api/cover?id=14421833', 'Years before he is president, Coriolanus Snow is a student assigned to mentor a tribute from District 12, Lucy Gray Baird, in the early and still unstable Hunger Games. His family''s status depends on her survival, and he begins to care about her in a way he can turn into strategy. The book follows the choices that teach him to treat affection, and other people, as threats to be managed.', 'Speculative', 'physical', null, null, '9781338635171', 'available', '2024-01-30T00:00:00.000Z'),
  ('10000000-0000-4000-8000-00000000001f', '00000000-0000-4000-8000-000000000001', 'Sunrise on the Reaping', 'Suzanne Collins', '/api/cover?id=14847912', 'This is Haymitch Abernathy''s story of the 50th Hunger Games, the Second Quarter Quell, in which twice the usual number of children were sent into the arena. It returns to the reaping that made him District 12''s victor and to the way the Capitol shaped what the country was allowed to remember about him. The novel is interested in the cost of surviving a story someone else gets to edit.', 'Speculative', 'physical', null, null, null, 'available', '2024-01-31T00:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000020', '00000000-0000-4000-8000-000000000001', 'In Half', 'Jasmin B. Frelih', null, 'Also published as In/Half. Twenty-five years after a collapse of global communications, three childhood friends approach their fiftieth birthdays in a world that can no longer speak to itself. Evan is staging a play in Tokyo, Kras is a former war minister surrounded by his family in a fortified Europe, and Zoja is preparing to read her poems in Brooklyn. The novel cuts between them as each tries to find a way back to a life that the broken world will not reassemble.', 'Speculative', 'physical', null, null, null, 'available', '2024-02-01T00:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000021', '00000000-0000-4000-8000-000000000001', 'The Handmaid''s Tale', 'Margaret Atwood', '/api/cover?id=8231851', 'In the Republic of Gilead, fertile women are assigned to powerful men as Handmaids and stripped of their names, work, and right to read. Offred, placed in the Commander''s house, remembers the daughter, the husband, and the ordinary life taken from her. Small violations of the rules, a market, a ceremony, a forbidden game of Scrabble, become the only room she has in which to remain a person.', 'Speculative', 'physical', null, null, '9780385490818', 'available', '2024-02-02T00:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000022', '00000000-0000-4000-8000-000000000001', '1984', 'George Orwell', '/api/cover?id=10541663', 'Winston Smith works at the Ministry of Truth, rewriting old newspapers so the past always agrees with the Party. He begins a secret diary and an affair with Julia, both of which are crimes against a government that watches through the telescreen. The novel follows what happens when he looks for a resistance and finds that the state wants not only his obedience but the contents of his mind.', 'Speculative', 'physical', null, null, '9780451524935', 'available', '2024-02-03T00:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000023', '00000000-0000-4000-8000-000000000001', 'Animal Farm', 'George Orwell', '/api/cover?id=11261770', 'The animals of Manor Farm drive out their farmer and write seven commandments for a society in which no animal will oppress another. The pigs, who appoint themselves the planners, begin to edit those commandments as soon as power is comfortable. The fable follows how a revolution spoken in the language of equality turns into a new version of the farmhouse it overthrew.', 'Speculative', 'physical', null, null, '9780451526342', 'available', '2024-02-04T00:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000024', '00000000-0000-4000-8000-000000000001', 'Lord of the Flies', 'William Golding', '/api/cover?id=8684447', 'A plane crash leaves a group of British schoolboys alone on an island with no adults. They elect a leader, keep a signal fire, and try to hold a meeting, and then fear, hunting, and a painted face begin to organize them more effectively than the rules do. The book watches a society invent its own monster and then become it.', 'Speculative', 'physical', null, null, '9780399501487', 'available', '2024-02-05T00:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000025', '00000000-0000-4000-8000-000000000001', 'I Who Have Never Known Men', 'Jacqueline Harpman', '/api/cover?id=7487522', 'A girl grows up in an underground cage with thirty-nine older women and male guards who never explain the rules. She has no memory of the world before the cage. When the guards disappear, the women walk out into an empty country, and she spends the rest of her life trying to read a civilization that seems to have ended without leaving her a way to ask why.', 'Speculative', 'physical', null, null, null, 'available', '2024-02-06T00:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000026', '00000000-0000-4000-8000-000000000001', 'The Elite', 'Kiera Cass', '/api/cover?id=7284838', 'America Singer has made it to the final group of the Selection, a televised competition for Prince Maxon''s hand and the crown. The palace is narrower and more dangerous at this stage: the remaining girls are rivals, the rebels outside are closer, and Maxon is no longer only a prize. America has to decide whether the life being offered is one she can stand to win.', 'Romance', 'physical', null, null, '9780062059963', 'available', '2024-02-07T00:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000027', '00000000-0000-4000-8000-000000000001', 'The One', 'Kiera Cass', '/api/cover?id=7284881', 'The Selection is down to its last choices, and the country is watching America as if the outcome were a wedding rather than a political arrangement. Rebels, a rival prince, and the girls still in the palace make the final weeks a question of loyalty as much as love. America has to choose what she will owe Maxon, and what she will refuse the crown, if she stays.', 'Romance', 'physical', null, null, '9780062059994', 'available', '2024-02-08T00:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000028', '00000000-0000-4000-8000-000000000001', 'If You Could See the Sun', 'Ann Liang', '/api/cover?id=12954164', 'Alice Sun is a scholarship student at an elite Beijing boarding school, working constantly to justify a place her classmates were born into. She discovers she can turn invisible, and invisibility turns out to be something other students will pay for. The favors get larger, and the cost of staying unseen starts to include the people she is trying not to lose.', 'Romance', 'physical', null, null, null, 'available', '2024-02-09T00:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000029', '00000000-0000-4000-8000-000000000001', 'Nothing Like the Movies', 'Lynn Painter', '/api/cover?id=15150672', 'The list said Nothing Like the Sun by Lin Painter. The novel on this shelf is Nothing Like the Movies by Lynn Painter, a romantic comedy about a second chance. Liz and Wes had a movie-shaped love story that broke, and a later meeting asks whether they can want each other without the script that made the first version look easy.', 'Romance', 'physical', null, null, '9781665947138', 'available', '2024-02-10T00:00:00.000Z'),
  ('10000000-0000-4000-8000-00000000002a', '00000000-0000-4000-8000-000000000001', 'Book Lovers', 'Emily Henry', '/api/cover?id=11567819', 'Nora Stephens is a New York literary agent who has been cast, more than once, as the cold city girlfriend in someone else''s small-town romance. A month in North Carolina with her sister puts her across the table from Charlie Lastra, an editor she already dislikes. The book is about two people who know the tropes and still have to find out what they want when the story will not follow them.', 'Romance', 'physical', null, null, '9780593440872', 'available', '2024-02-11T00:00:00.000Z'),
  ('10000000-0000-4000-8000-00000000002b', '00000000-0000-4000-8000-000000000001', 'Before I Go', 'Colleen Oakley', '/api/cover?id=10980977', 'Daisy has terminal cancer and becomes convinced that her husband, Jack, will not manage their life, or their dog, without her. She sets out to find him a new wife before she dies. The plan forces her to look at the marriage she is trying to replace herself in, and at the difference between loving someone and arranging them.', 'Romance', 'physical', null, null, null, 'available', '2024-02-12T00:00:00.000Z'),
  ('10000000-0000-4000-8000-00000000002c', '00000000-0000-4000-8000-000000000001', 'Slow Burn', 'Julie Garwood', '/api/cover?id=227458', 'Listed under Julia Garwood; the romantic suspense of this title is Julie Garwood''s. Kate MacKenna, who has built a fragrance business near Charleston, survives an explosion and then learns that her late mother left the company in debt. A second attempt on her life brings Dylan Buchanan, a Boston detective and her best friend''s brother, into her house. He is there to find out who wants her dead, and neither of them is good at pretending that is all he is there for.', 'Romance', 'physical', null, null, null, 'available', '2024-02-13T00:00:00.000Z'),
  ('10000000-0000-4000-8000-00000000002d', '00000000-0000-4000-8000-000000000001', 'Can You Keep a Secret?', 'Sophie Kinsella', '/api/cover?id=240064', 'Emma Corrigan, convinced the plane is going down, tells a sympathetic stranger every secret she has, including what she thinks of her job. He turns out to be Jack Harper, the head of the company she works for, and he remembers all of it. The comedy is what happens when the person who knows too much is also the person she has to face on Monday.', 'Romance', 'physical', null, null, '9780440241537', 'available', '2024-02-14T00:00:00.000Z'),
  ('10000000-0000-4000-8000-00000000002e', '00000000-0000-4000-8000-000000000001', 'Every Breath', 'Nicholas Sparks', '/api/cover?id=8600899', 'Hope Anderson is at her family''s cottage on Sunset Beach, trying to decide whether to marry the man waiting at home, when she meets Tru Walls beside a mailbox where strangers leave letters for the future. The days they spend together make the decision she came to settle feel less settled. The novel is about a brief meeting that rearranges two lives, and about the stories people tell so they can bear the ending.', 'Romance', 'physical', null, null, null, 'available', '2024-02-15T00:00:00.000Z'),
  ('10000000-0000-4000-8000-00000000002f', '00000000-0000-4000-8000-000000000001', 'Fine Things', 'Danielle Steel', '/api/cover?id=281853', 'Bernie Fine leaves the New York fashion office he knows and takes over a department store in San Francisco, where he falls in love with Liz and builds a family he did not expect. Loss, a child, and the people who depend on him keep rearranging the life he thought he was assembling. The novel follows him through the ordinary work of raising children and the blows that make that work the point.', 'Romance', 'physical', null, null, null, 'available', '2024-02-16T00:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000030', '00000000-0000-4000-8000-000000000001', 'The Seven Husbands of Evelyn Hugo', 'Taylor Jenkins Reid', '/api/cover?id=8354226', 'The reclusive film star Evelyn Hugo agrees to tell her life story to an unknown magazine reporter, Monique Grant, and no one can see why she has chosen her. Across seven marriages, Evelyn describes the career, the studio system, and the woman she actually loved. The interview is also a reckoning: Evelyn has picked Monique because their stories are already joined.', 'Romance', 'physical', null, null, '9781501161933', 'available', '2024-02-17T00:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000031', '00000000-0000-4000-8000-000000000001', 'Better Than the Movies', 'Lynn Painter', '/api/cover?id=11182600', 'Liz Buxbaum has planned her romantic life around her late mother''s favorite films, and the boy she wants is supposed to follow the script. The boy next door, Wes, is the person she has spent years treating as an obstacle. A bargain that throws them together forces her to notice that the person who knows her least convenient self is not the one the movies would have cast.', 'Romance', 'physical', null, null, '9781534467637', 'available', '2024-02-18T00:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000032', '00000000-0000-4000-8000-000000000001', 'Love from A to Z', 'S.K. Ali', '/api/cover?id=8795656', 'Adam and Zayneb meet in Doha and begin keeping the same kind of notebook, listing the marvels and the oddities of their days. She is a Muslim girl who has just been suspended for challenging an Islamophobic teacher. He is hiding a multiple sclerosis diagnosis from his father. The correspondence becomes a way of telling the truth before they are ready to say it aloud.', 'Romance', 'physical', null, null, '9781534442726', 'available', '2024-02-19T00:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000033', '00000000-0000-4000-8000-000000000001', 'Love Letters to the Dead', 'Ava Dellaira', '/api/cover?id=8764761', 'For a school assignment, Laurel writes a letter to Kurt Cobain and then keeps writing, to one dead artist after another, about the sister she lost and the things she has not told the living. The letters let her approach a secret about May and about herself without having to look at it directly. The book is about grief that borrows other people''s voices until it can stand to use its own.', 'Romance', 'physical', null, null, null, 'available', '2024-02-20T00:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000034', '00000000-0000-4000-8000-000000000001', 'Am I Normal Yet?', 'Holly Bourne', '/api/cover?id=10133837', 'Evie wants a clean start at sixth form: friends, a boyfriend, and no one who knows she has OCD. The recovery she is performing gets harder to maintain as the rituals return and the romance she wanted turns out to be another thing she has to manage. The novel treats getting well as uneven, and it is as interested in her female friendships as in the boy.', 'Romance', 'physical', null, null, null, 'available', '2024-02-21T00:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000035', '00000000-0000-4000-8000-000000000001', 'A Good Girl''s Guide to Murder', 'Holly Jackson', '/api/cover?id=13156188', 'For a school project, Pip Fitz-Amobi reopens the closed case of Andie Bell, the girl everyone believes was killed by her boyfriend Sal Singh. Pip starts with a spreadsheet and a polite doubt. Interviews, threatening notes, and the Singh family''s ruined name push the project past what a classroom assignment is supposed to cost.', 'Mystery', 'physical', null, null, '9781984896391', 'available', '2024-02-22T00:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000036', '00000000-0000-4000-8000-000000000001', 'Deception Point', 'Dan Brown', '/api/cover?id=14553479', 'NASA announces that it has found a meteorite in the Arctic containing proof of extraterrestrial life, and the discovery arrives just in time to rescue a president''s campaign. Intelligence analyst Rachel Sexton is sent to verify the find. What she and a small team uncover on the ice is less about science than about who needs the stone to be real.', 'Mystery', 'physical', null, null, '9780671027384', 'available', '2024-02-23T00:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000037', '00000000-0000-4000-8000-000000000001', 'Lolita', 'Vladimir Nabokov', '/api/cover?id=12984540', 'Humbert Humbert, a middle-aged scholar and a narrator who cannot be trusted, tells the story of his obsession with twelve-year-old Dolores Haze and of the captivity he calls a love affair. He marries her mother to stay near the child, and after the mother''s death he takes Dolores on a long drive across America. The prose is designed to seduce the reader into forgetting whose body the journey is built on.', 'Mystery', 'physical', null, null, '9780679723165', 'available', '2024-02-24T00:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000038', '00000000-0000-4000-8000-000000000001', 'The Double', 'Fyodor Dostoevsky', '/api/cover?id=11257679', 'Yakov Golyadkin, a minor civil servant in St. Petersburg, meets a man who looks exactly like him, shares his name, and begins to live his life more successfully than he does. The double charms Golyadkin''s colleagues and takes his place while Golyadkin protests in a way that makes him sound less and less sane. The novella is about a self that splits under humiliation and cannot persuade anyone that the split is real.', 'Mystery', 'physical', null, null, null, 'available', '2024-02-25T00:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000039', '00000000-0000-4000-8000-000000000001', 'The Midwife''s Daughter', 'Patricia Ferguson', '/api/cover?id=10786974', 'In a Cornish town before and during the First World War, Violet Dimond is the local handywoman who delivers babies the doctor does not bother with. Her twin brings her a dying child from an orphanage, a Black girl who resembles the daughter Violet lost, and Violet raises her as Grace. The novel moves among Violet, her sister, and Grace as the town''s prejudice and the war press on a household that had looked settled.', 'Literary', 'physical', null, null, null, 'available', '2024-02-26T00:00:00.000Z'),
  ('10000000-0000-4000-8000-00000000003a', '00000000-0000-4000-8000-000000000001', 'Rumi''s Daughter', 'Muriel Maufroy', '/api/cover?id=894274', 'The list named Muriel Maffrey. The novel is Muriel Maufroy''s story of Kimya, a girl in thirteenth-century Anatolia who is drawn into the circle of Rumi and his teacher Shams of Tabriz. Kimya is married into that household and has to make a spiritual life inside a love, and a jealousy, that the men around her treat as destiny. The book imagines the daughter and the wife at the edge of a story usually told only about the poet.', 'Literary', 'physical', null, null, null, 'available', '2024-02-27T00:00:00.000Z'),
  ('10000000-0000-4000-8000-00000000003b', '00000000-0000-4000-8000-000000000001', 'Best of Friends', 'Kamila Shamsie', '/api/cover?id=12953743', 'Maryam and Zahra grow up in Karachi as inseparable girls and meet again as powerful women in London, one in politics and one in finance. A secret from a single night in their teens has shaped what each of them thinks the other owes her. The novel follows a friendship across class, migration, and the moment when private loyalty collides with public power.', 'Literary', 'physical', null, null, '9781526647704', 'available', '2024-02-28T00:00:00.000Z'),
  ('10000000-0000-4000-8000-00000000003c', '00000000-0000-4000-8000-000000000001', 'The Bee Sting', 'Paul Murray', '/api/cover?id=14406691', 'The Barnes family, once comfortable in an Irish town, starts to come apart as Dickie''s car business fails and each of them tells a different story about why. Imelda is keeping the household together by charm and bargains, Cass is drinking through the end of school, and PJ is young enough to take the adults at their word. A secret in a car, and a bee sting on a wedding day, sit under the comedy until the book stops being funny.', 'Literary', 'physical', null, null, '9780374600303', 'available', '2024-02-29T00:00:00.000Z'),
  ('10000000-0000-4000-8000-00000000003d', '00000000-0000-4000-8000-000000000001', 'Blue Sisters', 'Coco Mellors', '/api/cover?id=14579522', 'Three sisters, Avery, Bonnie, and Lucky, return to one another after the death of their fourth sister, Nicky. Each has built a life that keeps the family at a distance: a lawyer in London, a boxer, a model. The year that follows asks them to look at the addiction and the grief they divided among themselves, and at whether they can be a family with one of them gone.', 'Literary', 'physical', null, null, null, 'available', '2024-03-01T00:00:00.000Z'),
  ('10000000-0000-4000-8000-00000000003e', '00000000-0000-4000-8000-000000000001', 'The Old Man and the Sea', 'Ernest Hemingway', '/api/cover?id=463307', 'Santiago, an old Cuban fisherman who has gone eighty-four days without a catch, rows out alone and hooks a giant marlin. The fight lasts for days and takes him far past the place where anyone could help him. What he brings back to the village is not the fish he fought for, and the story stays with the dignity of the fight rather than the market.', 'Literary', 'physical', null, null, '9780684801223', 'available', '2024-03-02T00:00:00.000Z'),
  ('10000000-0000-4000-8000-00000000003f', '00000000-0000-4000-8000-000000000001', 'To the Lighthouse', 'Virginia Woolf', '/api/cover?id=8231846', 'The Ramsay family and their guests spend a summer on the Isle of Skye, where a promised trip to the lighthouse is always about to happen and a painter, Lily Briscoe, is trying to finish a picture. A war and ten years pass in a short, brutal stretch of pages. When some of them return, the unfinished picture and the unfinished errand are still there, changed by who is missing.', 'Literary', 'physical', null, null, '9780156907392', 'available', '2024-03-03T00:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000040', '00000000-0000-4000-8000-000000000001', 'A Farewell to Arms', 'Ernest Hemingway', '/api/cover?id=7226599', 'Frederic Henry, an American ambulance driver on the Italian front in the First World War, falls in love with Catherine Barkley, an English nurse. The war is rain, injury, and a retreat that stops pretending to be orderly. They try to leave it for Switzerland, and the book stays inside the plain sentences of a happiness that the war has already made fragile.', 'Literary', 'physical', null, null, '9780684801469', 'available', '2024-03-04T00:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000041', '00000000-0000-4000-8000-000000000001', 'White Nights', 'Fyodor Dostoevsky', '/api/cover?id=14598226', 'A lonely man in St. Petersburg meets a young woman, Nastenka, on a bridge and spends four evenings listening to her wait for someone else. He offers her a feeling she is grateful for and cannot quite return. The novella is about a tenderness that knows, almost from the first night, that it is temporary.', 'Literary', 'physical', null, null, '9780140445562', 'available', '2024-03-05T00:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000042', '00000000-0000-4000-8000-000000000001', 'Notes from Underground', 'Fyodor Dostoevsky', '/api/cover?id=869632', 'A retired civil servant addresses the reader from a basement in St. Petersburg and argues, at length, with the idea that people can be improved by reason. He then tells the story of a dinner he forced his way into and a woman he tried to rescue in order to feel powerful. The book is a confession that keeps insulting the person who might have sympathized with it.', 'Literary', 'physical', null, null, '9780679734529', 'available', '2024-03-06T00:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000043', '00000000-0000-4000-8000-000000000001', 'The Bell Jar', 'Sylvia Plath', '/api/cover?id=8477115', 'Esther Greenwood wins a placement at a New York magazine and finds that the prizes she was promised do not make a life she can stand. The city, the men, and the plans other people make for her all start to look like the same glass closing overhead. The novel follows her breakdown and the slow, uneven work of coming back, without pretending the glass was a mood.', 'Literary', 'physical', null, null, '9780060837020', 'available', '2024-03-07T00:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000044', '00000000-0000-4000-8000-000000000001', 'The Metamorphosis', 'Franz Kafka', '/api/cover?id=6889547', 'Gregor Samsa wakes up as a giant insect and worries first about missing the train to work. His family, which has depended on his salary, has to decide what they owe a son they can no longer bear to see. The story stays inside the household: the food left at the door, the sister''s violin, and the relief that arrives when the inconvenience ends.', 'Literary', 'physical', null, null, '9780553213690', 'available', '2024-03-08T00:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000045', '00000000-0000-4000-8000-000000000001', 'The Catcher in the Rye', 'J.D. Salinger', '/api/cover?id=9273490', 'Holden Caulfield has just been expelled from another prep school and spends a few days in New York rather than go home and explain. He hires a cab, goes to bars, calls old friends, and keeps thinking about his younger sister Phoebe and about a brother who died. The novel is his voice for those days, funny and furious about every adult performance he can see through.', 'Literary', 'physical', null, null, '9780316769488', 'available', '2024-03-09T00:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000046', '00000000-0000-4000-8000-000000000001', 'The Picture of Dorian Gray', 'Oscar Wilde', '/api/cover?id=14314858', 'Dorian Gray wishes that a portrait of him would age in his place, and the wish is granted. He pursues pleasure, cruelty, and a life with no visible consequence, while the painting in the locked room records what he has done. The book asks what a person becomes when beauty is allowed to escape the bill.', 'Literary', 'physical', null, null, '9780141439570', 'available', '2024-03-10T00:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000047', '00000000-0000-4000-8000-000000000001', 'Anne of Green Gables', 'L.M. Montgomery', '/api/cover?id=14641084', 'Matthew and Marilla Cuthbert send for a boy to help on the farm and receive Anne Shirley, an orphan who talks without stopping and refuses to be sent back. Anne names the scenery, makes a fierce friend, and keeps getting into trouble that is mostly imagination meeting a strict household. The novel is about a child talking her way into a home that did not know it needed her.', 'Literary', 'physical', null, null, '9780553213133', 'available', '2024-03-11T00:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000048', '00000000-0000-4000-8000-000000000001', 'To Kill a Mockingbird', 'Harper Lee', '/api/cover?id=14351077', 'Scout Finch tells the story of the summer in Maycomb when her father, Atticus, defends a Black man, Tom Robinson, against a false charge. She and her brother Jem watch the trial, their neighbors, and the recluse Boo Radley from a child''s height. The book is about what a town is willing to know, and about the people it has agreed not to see.', 'Literary', 'physical', null, null, '9780061120084', 'available', '2024-03-12T00:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000049', '00000000-0000-4000-8000-000000000001', 'The Canterbury Tales', 'Geoffrey Chaucer', '/api/cover?id=5767180', 'A group of pilgrims on the road to Canterbury agrees to tell stories to pass the time, with the Host as judge. Knights, a miller, a wife from Bath, a pardoner, and the rest take turns, and each tale is a way of showing off, settling a score, or preaching. Chaucer''s poem is a portrait of medieval England told by people who cannot resist interrupting one another.', 'Classics', 'physical', null, null, null, 'available', '2024-03-13T00:00:00.000Z'),
  ('10000000-0000-4000-8000-00000000004a', '00000000-0000-4000-8000-000000000001', 'Romeo and Juliet', 'William Shakespeare', '/api/cover?id=8257991', 'The children of two feuding Verona families meet at a party, marry in secret, and have almost no time before the feud catches up with them. A friar''s plan involving a sleeping potion depends on a message that does not arrive. The play is a tragedy about speed: love, anger, and bad news all move faster than anyone can correct.', 'Classics', 'physical', null, null, '9780743477116', 'available', '2024-03-14T00:00:00.000Z'),
  ('10000000-0000-4000-8000-00000000004b', '00000000-0000-4000-8000-000000000001', 'Wuthering Heights', 'Emily Brontë', '/api/cover?id=12818862', 'Lockwood rents a house on the Yorkshire moors and hears, from the housekeeper, the story of Heathcliff and Catherine Earnshaw. Their attachment survives childhood, a bad marriage, and Catherine''s death, and it curdles into a revenge that takes in the next generation. The novel is a gothic romance in which love is not a remedy for anything.', 'Classics', 'physical', null, null, '9780141439556', 'available', '2024-03-15T00:00:00.000Z'),
  ('10000000-0000-4000-8000-00000000004c', '00000000-0000-4000-8000-000000000001', 'Pride and Prejudice', 'Jane Austen', '/api/cover?id=14348537', 'Mrs. Bennet is determined to marry off five daughters before her husband''s estate passes away from them. Elizabeth Bennet dislikes the proud Mr. Darcy on sight, and he gives her several good reasons to keep disliking him. The novel is a comedy of misreading, money, and the slow correction of two people who are both sure they are the perceptive one.', 'Classics', 'physical', null, null, '9780141439518', 'available', '2024-03-16T00:00:00.000Z'),
  ('10000000-0000-4000-8000-00000000004d', '00000000-0000-4000-8000-000000000001', 'Pride and Prejudice', 'Jane Austen', '/api/cover?id=14348537', 'Mrs. Bennet is determined to marry off five daughters before her husband''s estate passes away from them. Elizabeth Bennet dislikes the proud Mr. Darcy on sight, and he gives her several good reasons to keep disliking him. The novel is a comedy of misreading, money, and the slow correction of two people who are both sure they are the perceptive one. This is the second copy.', 'Classics', 'physical', null, null, '9780141439518', 'available', '2024-03-17T00:00:00.000Z'),
  ('10000000-0000-4000-8000-00000000004e', '00000000-0000-4000-8000-000000000001', 'Persuasion', 'Jane Austen', '/api/cover?id=12824691', 'Eight years before the book opens, Anne Elliot was persuaded to refuse Captain Wentworth because he had no fortune. He returns rich, and still angry, while Anne''s vain family is forced to rent out their house. The novel follows a quiet woman who has spent the interval being useful to other people, and a second chance that arrives without announcing itself.', 'Classics', 'physical', null, null, '9780141439686', 'available', '2024-03-18T00:00:00.000Z'),
  ('10000000-0000-4000-8000-00000000004f', '00000000-0000-4000-8000-000000000001', 'Emma', 'Jane Austen', '/api/cover?id=9278312', 'Emma Woodhouse, handsome, clever, and rich, appoints herself the matchmaker of Highbury and is wrong with great confidence. Her project for Harriet Smith collides with the feelings of the people closest to her, including Mr. Knightley, who has always told her the truth. The comedy is about a woman learning that charm is not the same thing as sight.', 'Classics', 'physical', null, null, '9780141439587', 'available', '2024-03-19T00:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000050', '00000000-0000-4000-8000-000000000001', 'Jane Eyre', 'Charlotte Brontë', '/api/cover?id=8235363', 'Jane, an orphan who survives a cruel aunt and a harsher school, takes a post as governess at Thornfield Hall and falls in love with her employer, Mr. Rochester. The house is keeping a secret on the third floor. When that secret comes out, Jane refuses a marriage that would cost her self-respect, and the novel follows her until she can come back on her own terms.', 'Classics', 'physical', null, null, '9780141441146', 'available', '2024-03-20T00:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000051', '00000000-0000-4000-8000-000000000001', 'Anna Karenina', 'Leo Tolstoy', '/api/cover?id=12327215', 'Anna leaves her husband and son for an affair with Count Vronsky, and Petersburg makes sure she pays for it in public. Alongside that descent, the novel follows Levin, a landowner trying to work out how to live decently with his wife, his farm, and his faith. Tolstoy sets a society love story and a domestic one in the same seasons, and lets them answer each other.', 'Classics', 'physical', null, null, '9780143035008', 'available', '2024-03-21T00:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000052', '00000000-0000-4000-8000-000000000001', 'The Sun Also Rises', 'Ernest Hemingway', '/api/cover?id=78741', 'A group of American and British expatriates drifts between Paris cafés and the bullfights at Pamplona in the years after the First World War. Jake Barnes loves Lady Brett Ashley and cannot be her lover. The novel is about people filling the days with drink, travel, and wit because the war has already decided what kind of life they get to have.', 'Classics', 'physical', null, null, '9780743297332', 'available', '2024-03-22T00:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000053', '00000000-0000-4000-8000-000000000001', 'Train to Pakistan', 'Khushwant Singh', '/api/cover?id=568646', 'In the summer of 1947, the village of Mano Majra, where Sikhs and Muslims have lived together, is pulled into the violence of Partition. A local dacoit, a Western-educated social worker, and a police officer each fail the moment in a different way. The trains that begin to arrive full of the dead turn a border into something the village can no longer pretend is elsewhere.', 'South Asian', 'physical', null, null, '9780802132215', 'available', '2024-03-23T00:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000054', '00000000-0000-4000-8000-000000000001', 'The Bastard of Istanbul', 'Elif Shafak', '/api/cover?id=1119672', 'Asya Kazanci is a young woman in a chaotic Istanbul household of women, and Armanoush is an Armenian-American girl who comes to stay with the Turkish family her stepfather came from. Their meeting opens a history the Kazancis have managed not to discuss. The novel braids a family comedy with the Armenian genocide and with the silence that let one household go on eating breakfast.', 'South Asian', 'physical', null, null, '9780143112716', 'available', '2024-03-24T00:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000055', '00000000-0000-4000-8000-000000000001', 'The Ministry of Utmost Happiness', 'Arundhati Roy', '/api/cover?id=8055065', 'Anjum, a hijra, builds a guest house in a Delhi graveyard, and the people who come to her are the ones no ministry intends to count. A second story follows Tilo, Musa, and a child through Kashmir and the mainland''s wars. Roy''s novel gathers the abandoned, the militant, and the merely heartbroken into one long argument about who gets to be called Indian.', 'South Asian', 'physical', null, null, '9781524733155', 'available', '2024-03-25T00:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000056', '00000000-0000-4000-8000-000000000001', 'The Kite Runner', 'Khaled Hosseini', '/api/cover?id=14846827', 'Amir grows up in Kabul with Hassan, the servant''s son who is braver than he is and loyal in a way Amir does not repay. A betrayal in an alley, and Amir''s silence afterward, follows him to America. The novel is about going back, years later, to do a hard thing for Hassan''s child in a country that is no longer the one they flew kites in.', 'South Asian', 'physical', null, null, '9781594631931', 'available', '2024-03-26T00:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000057', '00000000-0000-4000-8000-000000000001', 'The God of Small Things', 'Arundhati Roy', '/api/cover?id=10513792', 'In Ayemenem, Kerala, the twins Estha and Rahel grow up inside a family that is proud, fearful, and careful about caste. A visit from their English cousin and their mother''s love for a Dalit man, Velutha, break the rules the household is organized to protect. The novel moves between the week everything happens and the adult lives of the twins, who never quite get out of that week.', 'South Asian', 'physical', null, null, '9780812979657', 'available', '2024-03-27T00:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000058', '00000000-0000-4000-8000-000000000001', 'Discontent and Its Civilizations', 'Mohsin Hamid', '/api/cover?id=10749025', 'Mohsin Hamid''s essays on Pakistan, identity, and the stories countries tell about who belongs. He writes as a novelist stepping outside the novel, skeptical of nationalism and of the demand that a person pick one civilization and stay there. The pieces move among Lahore, New York, and London, and they argue for a self that is allowed to be more than one thing.', 'South Asian', 'physical', null, null, null, 'available', '2024-03-28T00:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000059', '00000000-0000-4000-8000-000000000001', 'Rogue States', 'Noam Chomsky', '/api/cover?id=6643697', 'Noam Chomsky''s essays on American foreign policy and the habit of calling other countries rogue while exempting one''s own. He reads interventions, sanctions, and official language against the record of what those policies did to the people on the receiving end. The book is political argument, kept on this shelf with the South Asian political writing rather than with the novels.', 'South Asian', 'physical', null, null, '9780896086111', 'available', '2024-03-29T00:00:00.000Z'),
  ('10000000-0000-4000-8000-00000000005a', '00000000-0000-4000-8000-000000000001', 'Blasphemy', 'Tehmina Durrani', '/api/cover?id=5417840', 'Tehmina Durrani''s novel, drawn from a woman''s account of life inside a feudal shrine in Pakistan. The narrator is married to a pir who uses religious authority to control the women and the tenants around him. The book describes violence that the community agrees not to name, and a woman''s slow decision to speak anyway.', 'South Asian', 'physical', null, null, null, 'available', '2024-03-30T00:00:00.000Z'),
  ('10000000-0000-4000-8000-00000000005b', '00000000-0000-4000-8000-000000000001', 'Dastan-e Mujahid', 'Naseem Hijazi', null, 'Naseem Hijazi''s first Urdu historical novel, set in the Umayyad period, when Muslim armies were moving at once into Spain, Sindh, Central Asia, and North Africa. It follows the campaigns associated with Tariq ibn Ziyad, Muhammad ibn Qasim, and Qutayba ibn Muslim. The book treats the soldier''s faith, discipline, and hardship as the story, rather than a single household.', 'South Asian', 'physical', null, null, null, 'available', '2024-03-31T00:00:00.000Z'),
  ('10000000-0000-4000-8000-00000000005c', '00000000-0000-4000-8000-000000000001', 'Ariel', 'Sylvia Plath', '/api/cover?id=33279', 'Sylvia Plath''s last poems, written in a blaze in the months before her death and published after it. They take on a father, a beekeeper, a birth, a ride on a horse, and a fury that the earlier work had held more carefully. The collection is the one readers mean when they talk about her as a confessional poet.', 'Poetry', 'physical', null, null, '9780060931728', 'available', '2024-04-01T00:00:00.000Z'),
  ('10000000-0000-4000-8000-00000000005d', '00000000-0000-4000-8000-000000000001', 'The Colossus', 'Sylvia Plath', '/api/cover?id=228566', 'Plath''s first book of poems, published in 1960, before the voice of Ariel. The poems are formally held, full of myth, fathers, and landscapes, and they show her building the control that the later work would break. It is the doorway into the poems, not the storm itself.', 'Poetry', 'physical', null, null, '9780679720731', 'available', '2024-04-02T00:00:00.000Z'),
  ('10000000-0000-4000-8000-00000000005e', '00000000-0000-4000-8000-000000000001', 'An Anthology of English Poetry', 'Oxford University Press', '/api/cover?id=14844732', 'An Oxford anthology of English verse, the shelf''s collection of other people''s poems rather than a single poet''s book. It runs from the older tradition through the voices a university press decided were the ones to keep. It could have lived with the reference books. It lives here because it is still a book of poems.', 'Poetry', 'physical', null, null, null, 'available', '2024-04-03T00:00:00.000Z'),
  ('10000000-0000-4000-8000-00000000005f', '00000000-0000-4000-8000-000000000001', 'The Soul of Rumi', 'Coleman Barks', '/api/cover?id=31918', 'Coleman Barks''s selection and English rendering of poems by Jalaluddin Rumi. The verses are about longing, friendship with the divine, and the kind of love that undoes the person who feels it. This is a reading version of Rumi rather than a scholarly edition, meant to be opened at random and read aloud.', 'Poetry', 'physical', null, null, null, 'available', '2024-04-04T00:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000060', '00000000-0000-4000-8000-000000000001', 'Rumi: Swallowing the Sun', 'Franklin D. Lewis', null, 'Franklin Lewis''s book on Rumi as both poet and historical figure, with translations set beside an account of how the poems were made and later remade. It is for a reader who wants the verses and also the context: the teacher Shams, the Mevlevi tradition, and the distance between the Persian and the versions in English. Scholarship and poetry share the same pages.', 'Poetry', 'physical', null, null, null, 'available', '2024-04-05T00:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000061', '00000000-0000-4000-8000-000000000001', 'The Nectar of Pain', 'Najwa Zebian', '/api/cover?id=8839498', 'Najwa Zebian''s poems about heartbreak, self-worth, and the unglamorous work of leaving a love that asked her to disappear. The voice is direct, closer to a letter than to a formal ode, and it is written for someone in the middle of repairing herself. The book is contemporary poetry about healing, not a novel that happens to be short.', 'Poetry', 'physical', null, null, '9781449492892', 'available', '2024-04-06T00:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000062', '00000000-0000-4000-8000-000000000001', 'The Sun and Her Flowers', 'Rupi Kaur', '/api/cover?id=8084615', 'Rupi Kaur''s second collection, arranged as a life moving through wilting, falling, rooting, rising, and blooming. The poems talk about assault, mothers, immigration, and the slow decision to treat one''s own body as home. They are short, illustrated, and meant to be read as a sequence rather than as separate lyrics.', 'Poetry', 'physical', null, null, '9781449486792', 'available', '2024-04-07T00:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000063', '00000000-0000-4000-8000-000000000001', 'The Forty Rules of Love', 'Elif Shafak', '/api/cover?id=9078986', 'This is a novel, not a book of verse. Ella Rubinstein, an unhappy American housewife, begins reading a manuscript about Rumi and Shams of Tabriz and starts a correspondence with its author. The novel alternates her suburban life with the thirteenth-century story of the poet and the wandering dervish who upended it.', 'Poetry', 'physical', null, null, '9780141047188', 'available', '2024-04-08T00:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000064', '00000000-0000-4000-8000-000000000001', 'The Prophet', 'Khalil Gibran', '/api/cover?id=418324', 'Kahlil Gibran''s book of prose poems, not a novel about a mystic. Before Almustafa leaves the city of Orphalese, the people ask him for talks on love, work, children, pain, and death, and he answers. The chapters are short enough to read as speeches, and they have been treated for a century as advice rather than as plot.', 'Poetry', 'physical', null, null, '9780394404288', 'available', '2024-04-09T00:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000065', '00000000-0000-4000-8000-000000000001', 'Steve Jobs', 'Walter Isaacson', '/api/cover?id=12374726', 'Walter Isaacson''s biography, written with Jobs''s cooperation and with access to the people he admired and the people he wounded. It follows him from a California childhood through Apple, the years in exile, Pixar, and the return, and it does not separate the products from the way he treated the teams that made them. The portrait is of a man who believed taste was a moral position and often used that belief as a weapon.', 'Memoir', 'physical', null, null, '9781451648539', 'available', '2024-04-10T00:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000066', '00000000-0000-4000-8000-000000000001', 'The Diary of a Young Girl', 'Anne Frank', '/api/cover?id=13521319', 'Anne Frank''s diary, kept in the secret annex in Amsterdam where her family hid from the Nazis from 1942 until they were found. She writes about the people in the rooms, her mother, her changing body, and the person she is trying to become, often with a sharpness that the hiding cannot dull. The book ends when the diary does, at the arrest, and the reader has to bring the rest of the history to the last page.', 'Memoir', 'physical', null, null, '9780553296983', 'available', '2024-04-11T00:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000067', '00000000-0000-4000-8000-000000000001', 'The Rugmaker of Mazar-e-Sharif', 'Najaf Mazari', '/api/cover?id=12759196', 'Najaf Mazari''s memoir of a boyhood in Afghanistan, a life as a rugmaker, and the flight from the Taliban that eventually brought him to Australia. He tells the story of learning a craft that is also a language of pattern and patience, and of a refugee system that did not know what to do with either. The book is an account of making a life again in a country that began as a detention center.', 'Memoir', 'physical', null, null, null, 'available', '2024-04-12T00:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000068', '00000000-0000-4000-8000-000000000001', 'In My Mother''s Footsteps', 'Mona Hajjar Halaby', '/api/cover?id=11577349', 'Mona Hajjar Halaby, raised in the diaspora, returns to Jerusalem and walks the city her mother had to leave. The memoir is a daughter''s attempt to match family stories to streets, checkpoints, and the neighbors who remained. It is about Palestinian memory carried by someone who did not live the original departure and cannot visit it as a tourist.', 'Memoir', 'physical', null, null, null, 'available', '2024-04-13T00:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000069', '00000000-0000-4000-8000-000000000001', 'Before the Coffee Gets Cold', 'Toshikazu Kawaguchi', '/api/cover?id=10138333', 'In a small Tokyo café, customers may return to a moment in the past if they sit in one particular chair and finish their coffee before it cools. The rules are strict: you cannot change the present, and you cannot leave the seat. Four visitors try anyway, each of them hoping that a conversation they failed to have might still be worth having.', 'East Asian', 'physical', null, null, '9781335430991', 'available', '2024-04-14T00:00:00.000Z'),
  ('10000000-0000-4000-8000-00000000006a', '00000000-0000-4000-8000-000000000001', 'Days at the Morisaki Bookshop', 'Satoshi Yagisawa', '/api/cover?id=13482084', 'Takako loses her job and her boyfriend in the same blow and hides in her uncle''s used bookshop in Jimbocho. She sleeps among the stacks, resists reading, and slowly begins to pick up the books and the regulars. The novel is a quiet story about a young woman coming back to life in a shop that has been doing the same work for a long time.', 'East Asian', 'physical', null, null, '9780063278677', 'available', '2024-04-15T00:00:00.000Z'),
  ('10000000-0000-4000-8000-00000000006b', '00000000-0000-4000-8000-000000000001', 'I Want to Die but I Want to Eat Tteokbokki', 'Baek Se-hee', null, 'Baek Se-hee''s record of her sessions with a psychiatrist, written from the notes she kept afterward. She describes a depression that does not cancel out ordinary appetites: she wants to die, and she also wants to eat tteokbokki, and both sentences are true on the same day. The book is a memoir of treatment, self-observation, and the awkward work of saying these things out loud.', 'East Asian', 'physical', null, null, '9781635579383', 'available', '2024-04-16T00:00:00.000Z'),
  ('10000000-0000-4000-8000-00000000006c', '00000000-0000-4000-8000-000000000001', 'Putting the Power of Your Subconscious Mind to Work', 'Joseph Murphy', '/api/cover?id=12825300', 'Joseph Murphy''s practical book on using the ideas in The Power of Your Subconscious Mind in ordinary work: habits, money, imagination, and the sentences a person repeats to themselves. It belongs to the New Thought tradition and treats the mind as something that can be aimed. The shelf keeps it as a self-help book, not as a novel.', 'Mind', 'physical', null, null, null, 'available', '2024-04-17T00:00:00.000Z'),
  ('10000000-0000-4000-8000-00000000006d', '00000000-0000-4000-8000-000000000001', 'The Artist''s Way', 'Julia Cameron', '/api/cover?id=10840008', 'Julia Cameron''s twelve-week course for people who have stopped making things. The method is concrete: morning pages, a weekly walk alone, and a series of tasks meant to loosen the grip of perfection and other people''s opinions. It is a workbook as much as an essay, and it asks the reader to do the assignments rather than agree with them.', 'Mind', 'physical', null, null, '9781585421466', 'available', '2024-04-18T00:00:00.000Z'),
  ('10000000-0000-4000-8000-00000000006e', '00000000-0000-4000-8000-000000000001', 'Are Men Obsolete?', 'Camille Paglia and Caitlin Moran', '/api/cover?id=12418488', 'The list said Camila Paglia. The book is a public debate between Camille Paglia and Caitlin Moran, two essays answering the question in the title and then answering each other. One argues from a long view of sex, art, and danger. The other argues from the daily politics of feminism now. It is an argument, not a verdict.', 'Mind', 'physical', null, null, '9781770894611', 'available', '2024-04-19T00:00:00.000Z'),
  ('10000000-0000-4000-8000-00000000006f', '00000000-0000-4000-8000-000000000001', 'Urdu Dictionary', 'Reference', null, 'A language dictionary, kept for looking a word up rather than for reading through. It sits with the other books that are tools: no plot, no narrator, and a different kind of use. The shelf treats it as part of the collection because it is in the room and it gets opened.', 'Reference', 'physical', null, null, null, 'available', '2024-04-20T00:00:00.000Z'),
  ('10000000-0000-4000-8000-000000000070', '00000000-0000-4000-8000-000000000001', 'University publication magazine', 'University publication', null, 'A student magazine from a university press run, more pamphlet than book. It is here because it was kept, not because it belongs to a genre. The open page can only describe it as an academic publication, a record of whatever issue this copy happens to be.', 'Reference', 'physical', null, null, null, 'available', '2024-04-21T00:00:00.000Z');
